// Read-only planning step: list engagements, then for each one whose tool_scope has rank
// pulls enabled, ask the platform (via the ALREADY-REAL search.rankSummary tool) when that
// property's rank was last captured. Due-ness is derived from tool_scope.rank.cadence, never
// hardcoded here (architect ruling, tracker #6j SM-15 point 3/4) -- an engagement whose scope
// editor says 'daily' gets checked against a 1-day window, 'weekly' against 7, etc., and a
// custom/absent cadence value defaults conservatively to weekly rather than guessing daily.
//
// Deliberately does its own HTTP calls in ONE all-items Code node rather than one HTTP Request
// node per engagement: this half is pure read-only planning (no money moves here), so keeping it
// in one place makes the due-check easy to audit as a unit. The actual paid action --
// search.pullRanks -- is its own explicit node below, so it stays visible in the execution log
// and is the one thing this flow ever writes.
//
// IDEMPOTENCY NOTE (see the ticket report for the full analysis): this due-check reads the
// PLATFORM's own last-capture timestamp, not n8n's local/static state -- so an n8n restart, a
// redeploy, or a manual re-trigger naturally becomes a no-op unless a pull is genuinely overdue,
// with no reliance on workflowStaticData surviving anything. The one gap this does NOT cover is
// two overlapping executions started within the same tick (e.g. a manual run racing the
// scheduled one): dispatchProviderOp's per-engagement advisory lock (design docs; already proven
// in SM-14) serializes the two calls, but does not dedupe them, because tracked-rank pulls always
// bypassCache=true by design (a rank pull must capture a live position, not a stale cached one) --
// so a genuine overlap can still cause two real dispatches. Not fixed here; flagged in the report.
const hubUrl = 'http://mcp-hub:3003/mcp';
const tenantId = $env.AGENCY_TENANT_ID;
const workflowId = 'wf:sm-rank-pull';

const callTool = async (name, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: hubUrl,
    headers: {
      Authorization: `Bearer ${$env.HUB_SERVICE_TOKEN}`,
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
      'x-obo-provider': 'n8n',
      'x-obo-external-id': workflowId,
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args } }),
  });
  const raw = typeof res === 'string' ? res : (res?.data ?? res?.body ?? JSON.stringify(res));
  const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
  if (!line) throw new Error(`${name}: no SSE data line in hub reply: ${String(raw).slice(0, 200)}`);
  const rpc = JSON.parse(line.slice(5).trim());
  if (rpc.result?.isError) throw new Error(rpc.result.content?.[0]?.text ?? `${name} failed`);
  return JSON.parse(rpc.result?.content?.[0]?.text ?? 'null');
};

const CADENCE_DAYS = { daily: 1, weekly: 7, monthly: 30 };

const engagements = await callTool('search.listEngagements', { tenantId });
const candidates = (Array.isArray(engagements) ? engagements : [])
  .filter((e) => e.status === 'active')
  .filter((e) => e.toolScope?.rank?.enabled === true && e.propertyId);

const due = [];
for (const eng of candidates) {
  const cadence = eng.toolScope?.rank?.cadence ?? 'weekly';
  const intervalDays = CADENCE_DAYS[cadence] ?? CADENCE_DAYS.weekly;
  let lastCapturedAt = null;
  try {
    const snapshots = await callTool('search.rankSummary', { tenantId, propertyId: eng.propertyId });
    lastCapturedAt = Array.isArray(snapshots) && snapshots.length ? snapshots[0].capturedAt : null;
  } catch (err) {
    // A read-only lookup failing for one property must not abort the rest of the tenant's sweep.
    continue;
  }
  const ageDays = lastCapturedAt ? (Date.now() - new Date(lastCapturedAt).getTime()) / 86400000 : Infinity;
  if (ageDays >= intervalDays) {
    due.push({
      json: {
        tenantId, engagementId: eng.id, propertyId: eng.propertyId,
        cadence, intervalDays, ageDays: Math.round(ageDays * 10) / 10,
      },
    });
  }
}
return due;

// Classify the pullRanks reply (automation/README.md's documented D14 pattern): a hub isError
// reply whose text starts with 'suspend:' means the write gate refused to run this MEDIUM-impact
// write unattended and it must be filed as a pending human approval, NOT treated as a failure and
// NOT retried. Any other isError is a genuine failure (SM-50 note: no retry here either -- the
// next scheduled tick, which will still see the same stale last-capture time, is the only retry).
const due = $('Compute due engagements (read-only)').item.json;
const raw = $input.item.json.data ?? $input.item.json.body ?? '';
const line = String(raw).split('\n').find((l) => l.startsWith('data:')) ?? '';
if (!line) return [{ json: { ...due, suspended: false, ok: false, error: 'no SSE data line in hub reply' } }];
const rpc = JSON.parse(line.slice(5).trim());
const text = rpc.result?.content?.[0]?.text ?? '';
if (rpc.result?.isError && text.startsWith('suspend:')) {
  return [{ json: { ...due, suspended: true, toolName: 'search.pullRanks', toolArgs: { tenantId: due.tenantId, engagementId: due.engagementId }, impact: 'medium', reason: text } }];
}
if (rpc.result?.isError) {
  return [{ json: { ...due, suspended: false, ok: false, error: text || 'search.pullRanks failed' } }];
}
const outcome = JSON.parse(text || '{}');
return [{ json: { ...due, suspended: false, ok: true, ...outcome } }];
